import type {
  DialogContentProps,
  DialogRootProps,
  DialogTitleProps,
  DialogTriggerProps,
} from '@designharness/primitives';
import { Dialog as DialogPrimitive } from '@designharness/primitives';
import { type ReactNode, forwardRef } from 'react';
import { cx, element, modifier } from './internal/classnames.js';
import { isPresent } from './internal/presence.js';

/**
 * Styled `Dialog`.
 *
 * `role="dialog"`/`alertdialog`, `aria-modal`, `aria-labelledby`, `aria-describedby`,
 * the focus trap, `Escape`/outside-click dismissal and the presence lifecycle all come
 * from the `@zag-js/dialog` machine behind the primitive. This layer sizes the surface,
 * lays it out with a container query and adds the footer element DESIGN.md asks for.
 */

/** Block class for every dialog selector in `styles/dialog.css`. */
export const DIALOG_BLOCK = 'dh-dialog';

/** Surface widths, mapped onto `--dialog-max-width-sm|md|lg`. */
export const DIALOG_SIZES = ['sm', 'md', 'lg'] as const;
export type DialogSize = (typeof DIALOG_SIZES)[number];

/** Anatomy root: context provider only, exactly like `Dialog.Root` in the primitives. */
export function DialogRoot(props: DialogRootProps): ReactNode {
  const { className, children, ...restProps } = props;
  return (
    <DialogPrimitive.Root {...restProps} className={cx(element(DIALOG_BLOCK, 'root'), className)}>
      {children}
    </DialogPrimitive.Root>
  );
}

export type UIDialogContentProps = DialogContentProps & {
  /** Surface width step. @default "md" */
  size?: DialogSize | undefined;
};

/** Class list for the dialog surface; exported so tests and stories can assert the mapping. */
export function dialogContentClassNames(size: DialogSize = 'md', className?: string | undefined): string {
  return cx(DIALOG_BLOCK, modifier(DIALOG_BLOCK, size), className);
}

/**
 * The dialog surface. `size` selects `--dialog-max-width-*` and the `@container`
 * breakpoint for the header/body/footer arrangement; `data-state`, `role` and the
 * labelled-by/described-by wiring stay machine-owned.
 */
export const DialogContent = forwardRef<HTMLDivElement, UIDialogContentProps>(function DialogContent(props, ref) {
  const { size, className, children, ...restProps } = props;
  return (
    <DialogPrimitive.Content {...restProps} ref={ref} className={dialogContentClassNames(size, className)}>
      {children}
    </DialogPrimitive.Content>
  );
});

/** Close trigger with the styled layer's glyph; `aria-label="Close"` comes from the primitive. */
export function DialogCloseTrigger(props: DialogTriggerProps): ReactNode {
  const { children, className, ...restProps } = props;
  return (
    <DialogPrimitive.CloseTrigger {...restProps} className={cx(element(DIALOG_BLOCK, 'close'), className)}>
      {children ?? <span className={element(DIALOG_BLOCK, 'close-glyph')} aria-hidden="true">×</span>}
    </DialogPrimitive.CloseTrigger>
  );
}

/** Heading wrapper so the title and the close trigger share one row. */
export function DialogTitle(props: DialogTitleProps): ReactNode {
  const { className, ...restProps } = props;
  return <DialogPrimitive.Title {...restProps} className={cx(element(DIALOG_BLOCK, 'title'), className)} />;
}

export type UIDialogProps = Omit<DialogRootProps, 'children' | 'className'> & {
  /** Dialog title. Required: an unnamed dialog is an accessibility defect, not a style. */
  title: ReactNode;
  /** Surface width step. @default "md" */
  size?: DialogSize | undefined;
  /** Footer content, right-aligned on wide surfaces (DESIGN.md: action row). */
  footer?: ReactNode | undefined;
  /** Trigger label. Omit it to drive the dialog with `open` instead. */
  trigger?: ReactNode | undefined;
  /** Props for the rendered trigger (e.g. `variant`-styled `Button`). */
  triggerProps?: DialogTriggerProps | undefined;
  /** Render the close trigger in the header. @default true */
  closable?: boolean | undefined;
  /** Body content. */
  children: ReactNode;
  className?: string | undefined;
};

/**
 * Complete dialog: trigger, backdrop, positioner, sized surface, header with close
 * trigger, body and an optional footer row.
 */
export function UIDialog(props: UIDialogProps): ReactNode {
  const { title, size = 'md', footer, trigger, triggerProps, closable = true, children, className, ...restProps } = props;

  return (
    <DialogRoot {...restProps} className={className}>
      {isPresent(trigger) ? <DialogPrimitive.Trigger {...triggerProps}>{trigger}</DialogPrimitive.Trigger> : null}
      <DialogPrimitive.Backdrop />
      <DialogPrimitive.Positioner>
        <DialogContent size={size}>
          <DialogPrimitive.Header className={element(DIALOG_BLOCK, 'header')}>
            <DialogTitle>{title}</DialogTitle>
            {closable ? <DialogCloseTrigger /> : null}
          </DialogPrimitive.Header>
          <DialogPrimitive.Body className={element(DIALOG_BLOCK, 'body')}>{children}</DialogPrimitive.Body>
          {isPresent(footer) ? <div className={element(DIALOG_BLOCK, 'footer')}>{footer}</div> : null}
        </DialogContent>
      </DialogPrimitive.Positioner>
    </DialogRoot>
  );
}

/** Callable dialog plus the frozen compound parts. */
export interface DialogComponent {
  (props: UIDialogProps): ReactNode;
  Root: typeof DialogRoot;
  Trigger: typeof DialogPrimitive.Trigger;
  Backdrop: typeof DialogPrimitive.Backdrop;
  Positioner: typeof DialogPrimitive.Positioner;
  Content: typeof DialogContent;
  Header: typeof DialogPrimitive.Header;
  Title: typeof DialogTitle;
  Body: typeof DialogPrimitive.Body;
  CloseTrigger: typeof DialogCloseTrigger;
}

export const Dialog: DialogComponent = Object.assign(UIDialog, {
  Root: DialogRoot,
  Trigger: DialogPrimitive.Trigger,
  Backdrop: DialogPrimitive.Backdrop,
  Positioner: DialogPrimitive.Positioner,
  Content: DialogContent,
  Header: DialogPrimitive.Header,
  Title: DialogTitle,
  Body: DialogPrimitive.Body,
  CloseTrigger: DialogCloseTrigger,
});

/*
 * Dialog — styling for the frozen `dialog` anatomy: `root`, `trigger`, `backdrop`,
 * `positioner`, `content`, `header`, `title`, `body`, `close-trigger`, plus the footer
 * row DESIGN.md requires (a styled-layer element: `footer` is not a frozen anatomy part,
 * so it carries a class and never a `data-part`).
 *
 * The surface declares `container-type: inline-size`, so the header/body/footer
 * arrangement responds to the *dialog's own width* — a 24rem dialog in a drawer and a
 * 48rem dialog on a stage each self-arrange (RESEARCH.md §6.1).
 */

@layer components {
  [data-part="backdrop"]:where([data-scope="dialog"]) {
    position: fixed;
    inset: 0rem;
    /* DESIGN.md "Elevation & Depth": overlay elevation pairs a scrim with the shadow.
       The scrim token is a flat ink, so alpha is expressed as element opacity — the
       token gate forbids authored colour functions like `color-mix()`. The machine
       toggles `hidden`, so the scrim never intercepts pointer events while closed. */
    background-color: var(--color-scrim);
    opacity: 0.6;
    transition: opacity var(--duration-moderate) var(--easing-standard);
  }

  [data-part="positioner"]:where([data-scope="dialog"]) {
    position: fixed;
    inset: 0rem;
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    padding: var(--space-md);
  }

  /* --- the surface -------------------------------------------------------------- */

  [data-part="content"]:where([data-scope="dialog"]) {
    container-type: inline-size;
    box-sizing: border-box;
    inline-size: 100%;
    max-block-size: calc(100vb - var(--space-xxl));
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
    padding: var(--dialog-padding);
    border-width: var(--border-width-hairline);
    border-style: solid;
    border-color: var(--color-border-strong);
    border-radius: var(--dialog-radius);
    background-color: var(--color-surface);
    color: var(--color-text-primary);
    font-family: var(--font-family-body);
    font-size: var(--font-size-body-md);
    line-height: var(--line-height-body-md);
    box-shadow: var(--elevation-2);
    opacity: 0;
    transition: opacity var(--duration-moderate) var(--easing-entry);
  }

  [data-part="content"][data-state="open"]:where([data-scope="dialog"]) {
    opacity: 1;
  }

  [data-part="content"][data-state="closed"]:where([data-scope="dialog"]) {
    transition-timing-function: var(--easing-exit);
  }

  /* The machine marks the surface `hidden` while it is closed. An authored `display`
     declaration outranks the UA `[hidden] { display: none }`, so honour it explicitly:
     a closed dialog must be neither painted nor hit-testable, and assistive technology
     must not be able to walk into it (WCAG 2.2 SC 4.1.2). */
  [data-part="content"][hidden]:where([data-scope="dialog"]) {
    display: none;
  }

  /* Width ladder from `--dialog-max-width-*`; the modifiers follow the block so the
     single-class specificity budget stays intact. */
  .dh-dialog {
    max-inline-size: var(--dialog-max-width-md);
  }

  .dh-dialog--sm {
    max-inline-size: var(--dialog-max-width-sm);
  }

  .dh-dialog--md {
    max-inline-size: var(--dialog-max-width-md);
  }

  .dh-dialog--lg {
    max-inline-size: var(--dialog-max-width-lg);
  }

  /* --- header, title, close ------------------------------------------------------ */

  .dh-dialog__header {
    display: flex;
    align-items: flex-start;
    gap: var(--space-sm);
  }

  [data-part="title"]:where([data-scope="dialog"]) {
    /* Fluid heading: no breakpoint jump between a rail and a stage (DESIGN.md
       "Typography"), still clamped inside the declared type scale. */
    font-size: clamp(
      var(--font-size-heading-3),
      calc(var(--font-size-body-md) + 1.5cqi),
      var(--font-size-heading-2)
    );
    font-family: var(--font-family-display);
    font-weight: var(--font-weight-heading-2);
    line-height: var(--line-height-heading-2);
    letter-spacing: var(--letter-spacing-heading-2);
    color: var(--color-text-primary);
    margin: 0rem;
    inline-size: 100%;
  }

  [data-part="close-trigger"]:where([data-scope="dialog"]) {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    box-sizing: border-box;
    margin: 0rem;
    inline-size: var(--control-height-md);
    min-block-size: var(--control-height-md);
    padding: 0rem;
    border-width: var(--border-width-hairline);
    border-style: solid;
    border-color: transparent;
    border-radius: var(--radius-sm);
    background-color: transparent;
    color: var(--color-text-secondary);
    cursor: default;
    transition:
      background-color var(--duration-fast) var(--easing-standard),
      border-color var(--duration-fast) var(--easing-standard),
      color var(--duration-fast) var(--easing-standard);
  }

  [data-part="close-trigger"]:where([data-scope="dialog"]):hover {
    background-color: var(--color-surface-sunken);
    border-color: var(--color-border-strong);
    color: var(--color-text-primary);
  }

  .dh-dialog__close-glyph {
    font-family: var(--font-family-body);
    font-size: var(--font-size-body-lg);
    line-height: var(--line-height-body-lg);
  }

  /* --- body ---------------------------------------------------------------------- */

  [data-part="body"]:where([data-scope="dialog"]) {
    /* Prose measure is 72ch (DESIGN.md "Layout"). */
    max-inline-size: 72ch;
    margin: 0rem;
    color: var(--color-text-primary);
    font-size: var(--font-size-body-md);
    line-height: var(--line-height-body-md);
    overflow-y: auto;
  }

  /* --- footer (styled-layer element, not an anatomy part) ------------------------ */

  .dh-dialog__footer {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    /* Never put two interactive targets closer than 8px (DESIGN.md "Don'ts"). */
    gap: var(--space-xs);
    justify-content: flex-end;
    border-block-start: var(--border-width-hairline) solid var(--color-border-subtle);
    padding-block-start: var(--space-sm);
  }

  .dh-dialog__footer > * {
    inline-size: 100%;
  }

  /* Wide surfaces: the action row right-aligns and sizes to its content. */
  @container (min-width: 40rem) {
    .dh-dialog__header {
      gap: var(--space-lg);
    }

    .dh-dialog__footer {
      flex-wrap: nowrap;
      padding-block-start: var(--space-md);
    }

    .dh-dialog__footer > * {
      inline-size: auto;
    }
  }
}

/**
 * Class-name helpers for the styled layer.
 *
 * The styled layer's only DOM contribution is *class names*: every structural and
 * state signal (`data-scope`, `data-part`, `data-open`, `data-disabled`, `aria-*`)
 * is owned by `@designharness/primitives` and is never re-implemented, renamed or
 * overridden here (TOKEN-API.md §5). Component CSS is authored against those
 * attributes plus the `dh-<component>` block / `dh-<component>--<variant>` modifier
 * classes produced by these helpers.
 */

/** Any value that a class list may legitimately contain. */
export type ClassValue = string | false | null | undefined;

/** Join a class list, dropping empty entries and collapsing to a single string. */
export function cx(...values: readonly ClassValue[]): string {
  const parts: string[] = [];
  for (const value of values) {
    if (typeof value === 'string' && value.length > 0) parts.push(value);
  }
  return parts.join(' ');
}

/**
 * BEM-ish modifier builder: `modifier('dh-button', 'primary')` → `dh-button--primary`.
 * A `false`/`undefined` modifier yields `undefined` so it can be passed to `cx` directly.
 */
export function modifier(block: string, value: string | false | null | undefined): string | undefined {
  if (!value) return undefined;
  return `${block}--${value}`;
}

/**
 * Element builder: `element('dh-button', 'spinner')` → `dh-button__spinner`.
 * Elements are markup *the styled layer itself renders* — never anatomy parts.
 */
export function element(block: string, name: string): string {
  return `${block}__${name}`;
}

/**
 * Merge a consumer `className` after the styled-layer classes so a host app can add
 * utility classes without ever losing the tokenized base (source order, no `!important`).
 */
export function withConsumerClass(styled: string, className: ClassValue): string {
  return cx(styled, className);
}

import type { ReactNode } from 'react';

/**
 * Returns true if the provided ReactNode is present (not undefined, null, false, or empty string).
 */
export const isPresent = (value: ReactNode): boolean =>
  value !== undefined && value !== null && value !== false && value !== '';
